// next-status preloader never fights the active video copy for I/O.
let copyQueue: Promise<unknown> = Promise.resolve();
function enqueueCopy<T>(fn: () => Promise<T>): Promise<T> {
  const next = copyQueue.then(() => fn(), () => fn());
