package expo.modules.safreader;

import android.content.ContentResolver;
import android.content.Context;
import android.database.Cursor;
import android.net.Uri;
import android.provider.DocumentsContract;

import com.facebook.react.bridge.Arguments;
import com.facebook.react.bridge.Promise;
import com.facebook.react.bridge.ReactApplicationContext;
import com.facebook.react.bridge.ReactContextBaseJavaModule;
import com.facebook.react.bridge.ReactMethod;
import com.facebook.react.bridge.WritableArray;
import com.facebook.react.bridge.WritableMap;

import java.io.FileOutputStream;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * SafReaderModule — native Android SAF scanner.
 *
 * All SAF I/O runs on a dedicated background ExecutorService, never on the JS
 * thread. This eliminates the Binder-IPC stalls (2-8 s on Samsung One UI,
 * Xiaomi MIUI, Realme/Oppo) that previously caused the JS thread to freeze
 * and trigger the ANR watchdog.
 *
 * Uses DocumentsContract.queryChildDocuments (one ContentResolver round-trip
 * per folder) instead of DocumentFile.listFiles() (one round-trip per file),
 * making the BFS ~10x faster on large folder trees.
 */
public class SafReaderModule extends ReactContextBaseJavaModule {

    private static final String MODULE_NAME = "SafReader";

    // Two threads: one for scan, one for concurrent copy operations.
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    // Only descend into folders on the known path to .Statuses.
    // Keeps BFS from wandering into DCIM, Downloads, etc.
    private static final Set<String> KNOWN_INTERMEDIATE = new HashSet<>(Arrays.asList(
        "android",
        "media",
        "com.whatsapp",
        "com.whatsapp.w4b",
        "whatsapp",
        "whatsapp business"
    ));

    private static final int    MAX_BFS_DEPTH   = 7;
    private static final long   BFS_TIMEOUT_MS  = 4000L;
    private static final int    COPY_BUFFER     = 65536;

    // Valid status file extensions (lower-case).
    private static final Set<String> VALID_EXTS = new HashSet<>(Arrays.asList(
        ".jpg", ".jpeg", ".png", ".gif", ".webp",
        ".mp4", ".mkv", ".3gp", ".mov"
    ));

    // DocumentsContract projection for child queries.
    private static final String[] CHILDREN_PROJECTION = {
        DocumentsContract.Document.COLUMN_DOCUMENT_ID,
        DocumentsContract.Document.COLUMN_DISPLAY_NAME,
        DocumentsContract.Document.COLUMN_MIME_TYPE,
        DocumentsContract.Document.COLUMN_LAST_MODIFIED,
        DocumentsContract.Document.COLUMN_SIZE,
    };

    public SafReaderModule(ReactApplicationContext reactContext) {
        super(reactContext);
    }

    @Override
    public String getName() {
        return MODULE_NAME;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Public API — all called from JS, all off-thread.
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Scan a granted SAF tree URI for .Statuses files.
     *
     * Resolves with an array of maps, each containing:
     *   uri      — content:// document URI (ready for expo-image / ExoPlayer)
     *   name     — display name (e.g. "img-20240102.jpg")
     *   mimeType — MIME type string
     *   modTime  — last-modified epoch ms (double)
     *   size     — file size in bytes (double)
     *
     * Rejects only on catastrophic errors; returns empty array if .Statuses
     * is not found or the BFS times out.
     */
    @ReactMethod
    public void scanForStatuses(String treeUriString, Promise promise) {
        executor.execute(() -> {
            try {
                Context context = getReactApplicationContext();
                ContentResolver resolver = context.getContentResolver();
                Uri treeUri = Uri.parse(treeUriString);

                String rootDocId = DocumentsContract.getTreeDocumentId(treeUri);
                long start = System.currentTimeMillis();

                String statusesDocId = findStatusesFolder(
                    resolver, treeUri, rootDocId, 0, start
                );

                if (statusesDocId == null) {
                    promise.resolve(Arguments.createArray());
                    return;
                }

                WritableArray result = readStatusFiles(resolver, treeUri, statusesDocId);
                promise.resolve(result);
            } catch (Exception e) {
                promise.reject("SAF_SCAN_ERROR", e.getMessage() != null ? e.getMessage() : "Unknown error", e);
            }
        });
    }

    /**
     * Copy a SAF content:// URI to a local file path using a 64 KB buffer.
     *
     * Running on a background thread means the JS thread is never blocked by
     * the ContentProvider Binder IPC during large-file copies (video files
     * are typically 1-10 MB and take 50-500 ms on OEM devices).
     *
     * Resolves with destPath on success; rejects on any I/O error.
     */
    @ReactMethod
    public void copyFileToCache(String contentUriString, String destPath, Promise promise) {
        executor.execute(() -> {
            InputStream in = null;
            FileOutputStream out = null;
            try {
                Context context = getReactApplicationContext();
                ContentResolver resolver = context.getContentResolver();
                Uri sourceUri = Uri.parse(contentUriString);

                in  = resolver.openInputStream(sourceUri);
                out = new FileOutputStream(destPath);

                if (in == null) {
                    promise.reject("COPY_ERROR", "Cannot open input stream for " + contentUriString);
                    return;
                }

                byte[] buf = new byte[COPY_BUFFER];
                int len;
                while ((len = in.read(buf)) != -1) {
                    out.write(buf, 0, len);
                }
                out.flush();
                promise.resolve(destPath);
            } catch (Exception e) {
                promise.reject("COPY_ERROR", e.getMessage() != null ? e.getMessage() : "Copy failed", e);
            } finally {
                try { if (in  != null) in.close();  } catch (Exception ignored) {}
                try { if (out != null) out.close(); } catch (Exception ignored) {}
            }
        });
    }

    /**
     * Fetch size + modTime for a single SAF document without reading its bytes.
     *
     * Resolves with a map {name, size, modTime, mimeType}.
     */
    @ReactMethod
    public void getDocumentInfo(String contentUriString, Promise promise) {
        executor.execute(() -> {
            String[] proj = {
                DocumentsContract.Document.COLUMN_DISPLAY_NAME,
                DocumentsContract.Document.COLUMN_SIZE,
                DocumentsContract.Document.COLUMN_LAST_MODIFIED,
                DocumentsContract.Document.COLUMN_MIME_TYPE,
            };
            try {
                Context context = getReactApplicationContext();
                ContentResolver resolver = context.getContentResolver();
                Uri uri = Uri.parse(contentUriString);

                Cursor cursor = resolver.query(uri, proj, null, null, null);
                if (cursor != null && cursor.moveToFirst()) {
                    WritableMap info = Arguments.createMap();
                    info.putString("name",     cursor.getString(0));
                    info.putDouble("size",     cursor.getLong(1));
                    info.putDouble("modTime",  cursor.getLong(2));
                    info.putString("mimeType", cursor.getString(3));
                    cursor.close();
                    promise.resolve(info);
                } else {
                    if (cursor != null) cursor.close();
                    promise.reject("NOT_FOUND", "Document not found: " + contentUriString);
                }
            } catch (Exception e) {
                promise.reject("INFO_ERROR", e.getMessage() != null ? e.getMessage() : "Info query failed", e);
            }
        });
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Private helpers
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * BFS through the SAF tree to locate the ".Statuses" folder.
     *
     * Only descends into folders whose display name is in KNOWN_INTERMEDIATE
     * (case-insensitive), so we never waste time scanning DCIM, Downloads, etc.
     *
     * Returns the document ID of ".Statuses", or null if not found / timed out.
     */
    private String findStatusesFolder(
        ContentResolver resolver,
        Uri treeUri,
        String docId,
        int depth,
        long startTimeMs
    ) {
        if (depth > MAX_BFS_DEPTH) return null;
        if (System.currentTimeMillis() - startTimeMs > BFS_TIMEOUT_MS) return null;

        Uri childrenUri = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, docId);

        // Collect subdirectories to recurse into after scanning this level,
        // so we can return early the moment we find ".Statuses".
        List<String> subdirDocIds = new ArrayList<>();

        Cursor cursor = null;
        try {
            cursor = resolver.query(childrenUri, CHILDREN_PROJECTION, null, null, null);
            if (cursor == null) return null;

            while (cursor.moveToNext()) {
                String childDocId = cursor.getString(0);
                String name       = cursor.getString(1);
                String mime       = cursor.getString(2);

                if (name == null) continue;

                // Direct hit
                if (".Statuses".equals(name)) return childDocId;

                boolean isDir = DocumentsContract.Document.MIME_TYPE_DIR.equals(mime);
                if (isDir && KNOWN_INTERMEDIATE.contains(name.toLowerCase())) {
                    subdirDocIds.add(childDocId);
                }
            }
        } catch (Exception ignored) {
            return null;
        } finally {
            if (cursor != null) { try { cursor.close(); } catch (Exception ignored2) {} }
        }

        // Recurse into known intermediate dirs (BFS order by expanding level-by-level,
        // but because the tree is narrow, DFS is equally fine and simpler here).
        for (String sub : subdirDocIds) {
            if (System.currentTimeMillis() - startTimeMs > BFS_TIMEOUT_MS) break;
            String found = findStatusesFolder(resolver, treeUri, sub, depth + 1, startTimeMs);
            if (found != null) return found;
        }

        return null;
    }

    /**
     * Read all valid status files from the ".Statuses" folder using a single
     * ContentResolver query. Returns a WritableArray of file-info maps.
     */
    private WritableArray readStatusFiles(
        ContentResolver resolver,
        Uri treeUri,
        String statusesDocId
    ) {
        WritableArray result = Arguments.createArray();
        Uri childrenUri = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, statusesDocId);

        Cursor cursor = null;
        try {
            cursor = resolver.query(childrenUri, CHILDREN_PROJECTION, null, null, null);
            if (cursor == null) return result;

            while (cursor.moveToNext()) {
                String childDocId = cursor.getString(0);
                String name       = cursor.getString(1);
                String mime       = cursor.getString(2);
                long   modTime    = cursor.getLong(3);
                long   size       = cursor.getLong(4);

                // Skip hidden files and sub-directories.
                if (name == null || name.startsWith(".")) continue;
                if (DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)) continue;
                if (!isValidStatusFile(name)) continue;

                Uri fileUri = DocumentsContract.buildDocumentUriUsingTree(treeUri, childDocId);

                WritableMap item = Arguments.createMap();
                item.putString("uri",      fileUri.toString());
                item.putString("name",     name);
                item.putString("mimeType", mime != null ? mime : "");
                item.putDouble("modTime",  modTime);
                item.putDouble("size",     size);
                result.pushMap(item);
            }
        } catch (Exception ignored) {
            // Return whatever we collected so far.
        } finally {
            if (cursor != null) { try { cursor.close(); } catch (Exception ignored2) {} }
        }

        return result;
    }

    private boolean isValidStatusFile(String name) {
        String lower = name.toLowerCase();
        for (String ext : VALID_EXTS) {
            if (lower.endsWith(ext)) return true;
        }
        // Extensionless files: some OEM WhatsApp builds store statuses
        // as hash-only filenames with no extension inside .Statuses.
        return !lower.contains(".");
    }

    @Override
    public void onCatalystInstanceDestroy() {
        executor.shutdown();
        super.onCatalystInstanceDestroy();
    }
}

package expo.modules.safreader;

import com.facebook.react.ReactPackage;
import com.facebook.react.bridge.NativeModule;
import com.facebook.react.bridge.ReactApplicationContext;
import com.facebook.react.uimanager.ViewManager;

import java.util.Collections;
import java.util.List;

public class SafReaderPackage implements ReactPackage {

    @Override
    public List<NativeModule> createNativeModules(ReactApplicationContext reactContext) {
        return Collections.singletonList(new SafReaderModule(reactContext));
    }

    @Override
    public List<ViewManager> createViewManagers(ReactApplicationContext reactContext) {
        return Collections.emptyList();
    }
}

/**
 * SafReader — JS wrapper for the native Android SAF scanner module.
 *
 * On Android this resolves to the native Java SafReaderModule which runs all
 * SAF I/O on a background ExecutorService thread. On iOS / web the module is
 * absent and every function is a no-op / safe fallback so the JS bundle never
 * crashes in non-Android environments or in Expo Go (before a custom build).
 */
import { NativeModules, Platform } from 'react-native';

export interface NativeSafFile {
  uri: string;
  name: string;
  mimeType: string;
  modTime: number;
  size: number;
}

export interface NativeDocumentInfo {
  name: string;
  size: number;
  modTime: number;
  mimeType: string;
}

interface SafReaderNative {
  scanForStatuses(treeUri: string): Promise<NativeSafFile[]>;
  copyFileToCache(contentUri: string, destPath: string): Promise<string>;
  getDocumentInfo(contentUri: string): Promise<NativeDocumentInfo>;
}

const SafReaderNative: SafReaderNative | null =
  Platform.OS === 'android' ? (NativeModules.SafReader ?? null) : null;

/** True when the native module is linked (custom dev-client / EAS build). */
export function isAvailable(): boolean {
  return SafReaderNative !== null;
}

/**
 * Scan a granted SAF tree URI for .Statuses files.
 * Returns an empty array when the native module is unavailable (Expo Go).
 */
export function scanForStatuses(treeUri: string): Promise<NativeSafFile[]> {
  if (!SafReaderNative) return Promise.resolve([]);
  return SafReaderNative.scanForStatuses(treeUri);
}

/**
 * Copy a SAF content:// file to a local destPath using a 64 KB buffer on a
 * Java background thread. Much faster than expo-file-system copyAsync for
 * large files on Android 11+ OEM devices.
 */
export function copyFileToCache(contentUri: string, destPath: string): Promise<string> {
  if (!SafReaderNative) return Promise.reject(new Error('SafReader native module not linked'));
  return SafReaderNative.copyFileToCache(contentUri, destPath);
}

/**
 * Fetch metadata (size, modTime, mimeType) for a SAF document without reading
 * its content. Resolves with NativeDocumentInfo.
 */
export function getDocumentInfo(contentUri: string): Promise<NativeDocumentInfo> {
  if (!SafReaderNative) return Promise.reject(new Error('SafReader native module not linked'));
  return SafReaderNative.getDocumentInfo(contentUri);
}

/**
 * Expo config plugin — wires the native SafReaderModule into the Android build.
 *
 * What it does during `expo prebuild` (or EAS build):
 *   1. Copies SafReaderModule.java + SafReaderPackage.java into
 *      android/app/src/main/java/expo/modules/safreader/
 *   2. Adds `import expo.modules.safreader.SafReaderPackage;` to MainApplication
 *   3. Adds `packages.add(new SafReaderPackage());` to getPackages()
 *
 * React Native's autolinking does NOT pick up local Java modules unless they
 * have an expo-module.config.json wired through expo-modules-core, so we
 * register the package manually here.
 */
const { withMainApplication, withDangerousMod } = require('@expo/config-plugins');
const path = require('path');
const fs = require('fs');

const JAVA_SRC_DIR = path.join(__dirname, '..', 'modules', 'saf-reader', 'android', 'src', 'main', 'java');

const JAVA_FILES = [
  'expo/modules/safreader/SafReaderModule.java',
  'expo/modules/safreader/SafReaderPackage.java',
];

/**
 * Copy the Java source files into the generated android project.
 */
function withSafReaderJavaSources(config) {
  return withDangerousMod(config, [
    'android',
    (config) => {
      const androidJavaSrcDir = path.join(
        config.modRequest.projectRoot,
        'android',
        'app',
        'src',
        'main',
        'java',
      );

      for (const relPath of JAVA_FILES) {
        const src  = path.join(JAVA_SRC_DIR, relPath);
        const dest = path.join(androidJavaSrcDir, relPath);
        const destDir = path.dirname(dest);

        if (!fs.existsSync(destDir)) {
          fs.mkdirSync(destDir, { recursive: true });
        }

        if (fs.existsSync(src)) {
          fs.copyFileSync(src, dest);
        } else {
          console.warn(`[with-saf-reader] Source file not found: ${src}`);
        }
      }

      return config;
    },
  ]);
}

/**
 * Register SafReaderPackage in MainApplication.java/kt so React Native loads it.
 *
 * Handles both Java (.java) and Kotlin (.kt) MainApplication files, which
 * Expo generates depending on the template version.
 */
function withSafReaderMainApplication(config) {
  return withMainApplication(config, (config) => {
    let contents = config.modResults.contents;

    // Idempotent — don't add twice.
    if (contents.includes('SafReaderPackage')) return config;

    const isKotlin = config.modResults.language === 'kt';

    if (isKotlin) {
      // Kotlin MainApplication
      contents = contents.replace(
        /(import com\.facebook\.react\.ReactApplication)/,
        'import expo.modules.safreader.SafReaderPackage\n$1',
      );
      // Kotlin getPackages(): add before `return packages`
      contents = contents.replace(
        /(val packages = PackageList\(this\)\.packages)/,
        '$1\n      packages.add(SafReaderPackage())',
      );
      // Fallback pattern used by newer Expo Kotlin templates
      if (!contents.includes('SafReaderPackage()')) {
        contents = contents.replace(
          /(return packages)/,
          'packages.add(SafReaderPackage())\n      $1',
        );
      }
    } else {
      // Java MainApplication
      contents = contents.replace(
        /(import com\.facebook\.react\.ReactApplication;)/,
        '$1\nimport expo.modules.safreader.SafReaderPackage;',
      );
      // Standard Expo Java template pattern
      contents = contents.replace(
        /(List<ReactPackage> packages = new PackageList\(this\)\.getPackages\(\);)/,
        '$1\n      packages.add(new SafReaderPackage());',
      );
      // Fallback: older templates use `return packages;` directly
      if (!contents.includes('new SafReaderPackage()')) {
        contents = contents.replace(
          /(return packages;)/,
          'packages.add(new SafReaderPackage());\n      $1',
        );
      }
    }

    config.modResults.contents = contents;
    return config;
  });
}

function withSafReader(config) {
  config = withSafReaderJavaSources(config);
  config = withSafReaderMainApplication(config);
  return config;
}

module.exports = withSafReader;

