   671→      const knownUris = new Set(valid.map(v => v.localUri));
   672→      const knownNames = new Set(valid.map(v => v.name));
   673→      let after: string | undefined;
   674→      let pageGuard = 0;
   675→      let added = false;
   676→      while (pageGuard < 20) {
   677→        pageGuard += 1;
