  1693→    // time. Always awaits the full write before returning so the file
  1694→    // handed to Sharing.shareAsync is never half-written.
  1695→    //
  1696→    // FIX (2026-04-27): VERIFY + RETRY + THROW.
  1697→    //   The previous code silently caught any copy failure and returned
  1698→    //   `item.uri` (the original content:// URI). The viewer would then
  1699→    //   hand that URI to ExoPlayer, which buffers ~1 s of SAF bytes
  1700→    //   successfully, then stalls when it can't refill the buffer →
  1701→    //   "video plays for 1 second then freezes" for users on certain
  1702→    //   Android 11+ OEM SAF implementations. The fallback was masking a
  1703→    //   real failure as a worse-looking bug.
  1704→    //
  1705→    //   Now: copy → verify the destination file exists with size > 0
  1706→    //   → if not, delete the partial file and retry ONCE. If both
  1707→    //   attempts fail, throw so the caller can show its retry UI
  1708→    //   instead of letting the player silently freeze on a content://
  1709→    //   URI we already know is unplayable.
  1710→    // Use native Java copy when available — runs on a background thread so
  1711→    // the JS thread is never blocked during the Binder IPC. Falls back to
  1712→    // expo-file-system for Expo Go / non-native builds.
  1713→    const rawDest = tempUri.replace('file://', '');
  1714→    const useNativeCopy = item.uri.startsWith('content://') && SafReaderModule.isAvailable();
  1715→
  1716→    return enqueueCopy(async () => {
  1717→      for (let attempt = 1; attempt <= 2; attempt++) {
  1718→        try {
  1719→          __DEV__ && console.log(`[Media] (queue) Copying ${item.name} to cache (attempt ${attempt}, native=${useNativeCopy})...`);
  1720→          if (useNativeCopy) {
  1721→            await SafReaderModule.copyFileToCache(item.uri, rawDest);
  1722→          } else {
  1723→            await FileSystem.copyAsync({ from: item.uri, to: tempUri });
  1724→          }
  1725→          const verify = await FileSystem.getInfoAsync(tempUri);
  1726→          const size = (verify as any).size ?? 0;
  1727→          if (verify.exists && size > 0) {
  1728→            __DEV__ && console.log(`[Media] (queue) Copy complete for ${item.name} (${Date.now() - start}ms, ${size} bytes)`);
  1729→            return tempUri;
  1730→          }
  1731→          __DEV__ && console.warn(`[Media] (queue) Copy verify failed for ${item.name} (attempt ${attempt}): exists=${verify.exists}, size=${size}`);
  1732→          try { await FileSystem.deleteAsync(tempUri, { idempotent: true }); } catch {}
  1733→        } catch (e) {
  1734→          __DEV__ && console.warn(`[Media] (queue) Copy attempt ${attempt} threw for ${item.name}:`, e);
  1735→          try { await FileSystem.deleteAsync(tempUri, { idempotent: true }); } catch {}
  1736→        }
  1737→      }
  1738→      // Both attempts failed. Throw so the viewer's pre-copy effect can
  1739→      // catch it and surface the "Tap to retry" overlay.

