import { Stack, useRouter } from 'expo-router';
import * as SplashScreen from 'expo-splash-screen';
import React, { useEffect, useState, useRef } from 'react';
import { GestureHandlerRootView } from 'react-native-gesture-handler';
import { StatusBar } from 'expo-status-bar';
import { Platform, AppState, AppStateStatus, InteractionManager } from 'react-native';
import { useStableStatusBar } from '@/hooks/useStableStatusBar';
import {
  useFonts,
  Nunito_400Regular,
  Nunito_600SemiBold,
  Nunito_700Bold,
  Nunito_800ExtraBold,
} from '@expo-google-fonts/nunito';
import * as NavigationBar from 'expo-navigation-bar';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { ErrorBoundary } from '@/components/common/ErrorBoundary';
import { MediaProvider } from '@/contexts/MediaContext';
import { LanguageProvider } from '@/contexts/LanguageContext';
import { AppLoadingScreen } from '@/components/common/AppLoadingScreen';
import { useStatusReminder } from '@/hooks/media/useStatusReminder';
import { ThemeProvider, useTheme } from '@/contexts/ThemeContext';

// ── Production console hygiene ───────────────────────────────────────────
if (!__DEV__) {
  const noop = () => {};
  console.log   = noop;
  console.debug = noop;
  console.info  = noop;
  console.warn  = noop;
}

SplashScreen.preventAutoHideAsync();

async function applyImmersiveMode(bg: string, isDark: boolean) {
  if (Platform.OS !== 'android') return;
  try {
    const sdkVersion = Platform.Version as number;
    if (sdkVersion < 30) {
      await NavigationBar.setVisibilityAsync('visible');
    }
    await NavigationBar.setButtonStyleAsync(isDark ? 'light' : 'dark');
    if (sdkVersion < 35) {
      await NavigationBar.setBackgroundColorAsync(bg);
      await NavigationBar.setBehaviorAsync('inset-swipe');
    }
  } catch {}
}

function AppNavigator({ showOnboarding }: { showOnboarding: boolean }) {
  const { colors: COLORS } = useTheme();
  const router = useRouter();
  const onboardingNavigatedRef = useRef(false);

  useEffect(() => {
    if (showOnboarding && !onboardingNavigatedRef.current) {
      onboardingNavigatedRef.current = true;
      router.replace('/onboarding');
    }
  }, [showOnboarding]);

  return (
    <Stack
      screenOptions={{
        headerStyle: { backgroundColor: COLORS.SURFACE },
        headerTintColor: COLORS.TEXT,
        headerTitleStyle: {
          fontFamily: 'Nunito_700Bold',
          fontSize: 17,
          color: COLORS.TEXT,
        },
        headerShadowVisible: false,
        contentStyle: { backgroundColor: COLORS.BACKGROUND },
        animation: 'slide_from_right',
      }}
    >
      {showOnboarding && <Stack.Screen name="onboarding" options={{ headerShown: false }} />}
      <Stack.Screen name="(tabs)" options={{ headerShown: false }} />
      <Stack.Screen
        name="viewer"
        options={{
          headerShown: false,
          animation: 'fade',
          presentation: 'fullScreenModal',
        }}
      />
      <Stack.Screen
        name="guide"
        options={{ title: 'Setup Guide', headerStyle: { backgroundColor: COLORS.SURFACE } }}
      />
      <Stack.Screen
        name="privacy"
        options={{ title: 'Privacy', headerStyle: { backgroundColor: COLORS.SURFACE } }}
      />
      <Stack.Screen name="permissions" options={{ headerShown: false }} />
      <Stack.Screen name="languages" options={{ headerShown: false }} />
      <Stack.Screen name="terms" options={{ headerShown: false }} />
    </Stack>
  );
}

function DeferredStartupTasks() {
  useStatusReminder();
  return null;
}

function AppContentBody({ showOnboarding }: { showOnboarding: boolean }) {
  const { colors, resolved } = useTheme();

  useStableStatusBar({
    backgroundColor: resolved === 'dark' ? '#05070A' : '#FFFFFF',
    barStyle: resolved === 'dark' ? 'light-content' : 'dark-content',
    translucent: false,
  });

  useEffect(() => {
    applyImmersiveMode(colors.BACKGROUND, resolved === 'dark');
  }, [colors, resolved]);

  return (
    <MediaProvider>
      <StatusBar style={resolved === 'dark' ? 'light' : 'dark'} />
      <AppNavigator showOnboarding={showOnboarding} />
    </MediaProvider>
  );
}

function AppContent({ showOnboarding }: { showOnboarding: boolean }) {
  const [deferredReady, setDeferredReady] = useState(false);

  useEffect(() => {
    let cancelled = false;
    const handle = InteractionManager.runAfterInteractions(() => {
      const t = setTimeout(() => {
        if (!cancelled) setDeferredReady(true);
      }, 800);
      return () => clearTimeout(t);
    });
    return () => {
      cancelled = true;
      // @ts-ignore
      handle?.cancel?.();
    };
  }, []);

  return (
    <>
      <AppContentBody showOnboarding={showOnboarding} />
      {deferredReady && <DeferredStartupTasks />}
    </>
  );
}

const RootLayout = () => {
  const [fontsLoaded] = useFonts({
    Nunito_400Regular,
    Nunito_600SemiBold,
    Nunito_700Bold,
    Nunito_800ExtraBold,
  });
  const [loadingDone, setLoadingDone] = useState(false);
  const [splashHidden, setSplashHidden] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const appState = useRef(AppState.currentState);

  useEffect(() => {
    if (fontsLoaded) {
      SplashScreen.hideAsync();
      setSplashHidden(true);
    }
  }, [fontsLoaded]);

  useEffect(() => {
    checkOnboarding();
    const sub = AppState.addEventListener('change', (next: AppStateStatus) => {
      appState.current = next;
    });
    return () => sub.remove();
  }, []);

  const checkOnboarding = async () => {
    try {
      const completed = await AsyncStorage.getItem('onboarding_completed');
      if (completed === null) setShowOnboarding(true);
    } catch {
      setShowOnboarding(true);
    }
  };

  if (!fontsLoaded || !splashHidden) return null;

  if (!loadingDone) {
    return (
      <GestureHandlerRootView style={{ flex: 1 }}>
        <ThemeProvider>
          <StatusBar style="auto" />
          <AppLoadingScreen onDone={() => setLoadingDone(true)} />
        </ThemeProvider>
      </GestureHandlerRootView>
    );
  }

  return (
    <ErrorBoundary>
      <GestureHandlerRootView style={{ flex: 1 }}>
        <ThemeProvider>
          <LanguageProvider>
            <AppContent showOnboarding={showOnboarding} />
          </LanguageProvider>
        </ThemeProvider>
      </GestureHandlerRootView>
    </ErrorBoundary>
  );
};

export default RootLayout;

